import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const androidRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const workspaceRoot = resolve(androidRoot, '..');

const sources = {
  XTERM_CSS: resolve(workspaceRoot, 'node_modules/@xterm/xterm/css/xterm.css'),
  XTERM_JS: resolve(workspaceRoot, 'node_modules/@xterm/xterm/lib/xterm.js'),
  XTERM_FIT_JS: resolve(workspaceRoot, 'node_modules/@xterm/addon-fit/lib/addon-fit.js'),
};

const lines = [
  '// Generated by scripts/generate-terminal-assets.mjs. Do not edit by hand.',
  '// Sources are pinned by android/package.json and pnpm-lock.yaml.',
];

for (const [name, path] of Object.entries(sources)) {
  const contents = readFileSync(path, 'utf8');
  if (/<\/script/i.test(contents) || /<\/style/i.test(contents)) {
    throw new Error(`${path} contains an unsafe HTML closing tag`);
  }
  lines.push(`export const ${name} = ${JSON.stringify(contents)};`);
}

writeFileSync(
  resolve(androidRoot, 'src/terminal/xtermAssets.generated.ts'),
  `${lines.join('\n')}\n`,
  'utf8',
);
